from hermes_tools import terminal
script = r'''
from openpyxl import load_workbook
from openpyxl.utils import get_column_letter
path='/root/data/workbook.xlsx'
wb=load_workbook(path, data_only=False)
print('Sheet names:', wb.sheetnames)
ws=wb['Task']
print('\nTask sheet inspection')
for start,end in [(12,17),(19,24),(26,31)]:
    print(f'Column D rows {start}-{end}:')
    for r in range(start,end+1):
        print(f'  D{r} = {ws[f"D{r}"].value!r}')
print('Row 10 columns H-L (years):')
for c in range(8,13):
    print(f'  {get_column_letter(c)}10 = {ws.cell(10,c).value!r}')
print('Block/title labels near rows 11, 18, 25:')
for r in [11,18,25]:
    vals=[]
    for c in range(1,14):
        v=ws.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    print(f'  row {r}: ' + '; '.join(vals))
print('Rows 35-40 labels in column D:')
for r in range(35,41):
    print(f'  D{r} = {ws[f"D{r}"].value!r}')
print('Rows 42-47 labels in column C or D:')
for r in range(42,48):
    print(f'  C{r} = {ws[f"C{r}"].value!r}; D{r} = {ws[f"D{r}"].value!r}')
print(f'Row 50 label: C50={ws["C50"].value!r}; D50={ws["D50"].value!r}')

ds=wb['Data']
print('\nData sheet inspection')
print('Row 21 header row, used columns:')
row21=[]
for c in range(1, ds.max_column+1):
    v=ds.cell(21,c).value
    if v is not None:
        row21.append(f'{get_column_letter(c)}21={v!r}')
print('  ' + '; '.join(row21))
print('Sample rows 22-38 (non-empty cells):')
for r in range(22,39):
    vals=[]
    for c in range(1, ds.max_column+1):
        v=ds.cell(r,c).value
        if v is not None:
            vals.append(f'{get_column_letter(c)}{r}={v!r}')
    print(f'  row {r}: ' + '; '.join(vals))
# infer geometry
# series codes from task
series=set()
for r in list(range(12,18))+list(range(19,25))+list(range(26,32)):
    v=ws.cell(r,4).value
    if v is not None: series.add(str(v))
years=set()
for c in range(8,13):
    v=ws.cell(10,c).value
    if v is not None: years.add(v)
print('\nGeometry inference:')
for c in range(1, ds.max_column+1):
    matches=[]
    for r in range(22,39):
        if str(ds.cell(r,c).value) in series:
            matches.append(r)
    if matches:
        print(f'  Series code matches in column {get_column_letter(c)} rows {matches}')
for r in range(1, ds.max_row+1):
    matches=[]
    for c in range(1, ds.max_column+1):
        if ds.cell(r,c).value in years or str(ds.cell(r,c).value) in {str(y) for y in years}:
            matches.append(get_column_letter(c))
    if matches:
        print(f'  Year header matches in row {r} columns {matches}')
print('Conclusion: data appears organized with series codes in a column and years across columns if series-code matches are vertical and year matches are horizontal.')
'''
res=terminal("python3 - <<'PY'\n"+script+"\nPY", timeout=120, workdir='/root')
print(res['output'])
if res.get('exit_code') != 0:
    print('EXIT_CODE', res.get('exit_code'))
